<?php

namespace App\Http\Controllers;

use App\Models\Category;
use App\Models\Customer;
use App\Models\Product;
use App\Models\Sale;
use App\Models\SaleItem;
use Barryvdh\DomPDF\Facade\Pdf;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

class PosController extends Controller
{
    public function index()
    {
        $products = Product::with('category')->where('stock', '>', 0)->orderBy('name')->get();
        $categories = Category::orderBy('name')->get();

        return view('pos.index', compact('products', 'categories'));
    }

    public function store(Request $request)
    {
        $validated = $request->validate([
            'customer_name' => ['nullable', 'string', 'max:255'],
            'customer_phone' => ['nullable', 'string', 'max:30'],
            'discount' => ['nullable', 'numeric', 'min:0'],
            'paid_amount' => ['nullable', 'numeric', 'min:0'],
            'items' => ['required', 'array', 'min:1'],
            'items.*.product_id' => ['required', 'exists:products,id'],
            'items.*.quantity' => ['required', 'integer', 'min:1'],
        ]);

        $sale = DB::transaction(function () use ($validated, $request) {
            $customer = null;
            if (!empty($validated['customer_name']) || !empty($validated['customer_phone'])) {
                $customer = Customer::create([
                    'name' => $validated['customer_name'] ?? 'Walk-in Customer',
                    'phone' => $validated['customer_phone'] ?? null,
                ]);
            }

            $subTotal = 0;
            $lineItems = [];

            foreach ($validated['items'] as $item) {
                $product = Product::lockForUpdate()->findOrFail($item['product_id']);

                if ($product->stock < $item['quantity']) {
                    abort(422, "Insufficient stock for {$product->name}. Available: {$product->stock}");
                }

                $lineTotal = $product->sale_price * $item['quantity'];
                $subTotal += $lineTotal;

                $lineItems[] = [
                    'product' => $product,
                    'quantity' => $item['quantity'],
                    'price' => $product->sale_price,
                    'total' => $lineTotal,
                ];
            }

            $discount = $validated['discount'] ?? 0;
            $total = max($subTotal - $discount, 0);

            $sale = Sale::create([
                'invoice_no' => 'INV-' . now()->format('Ymd') . '-' . strtoupper(Str::random(5)),
                'customer_id' => $customer?->id,
                'user_id' => auth()->id(),
                'sub_total' => $subTotal,
                'discount' => $discount,
                'total' => $total,
                'paid_amount' => $validated['paid_amount'] ?? $total,
            ]);

            foreach ($lineItems as $line) {
                SaleItem::create([
                    'sale_id' => $sale->id,
                    'product_id' => $line['product']->id,
                    'quantity' => $line['quantity'],
                    'price' => $line['price'],
                    'total' => $line['total'],
                ]);

                $line['product']->decrement('stock', $line['quantity']);
            }

            return $sale;
        });

        return response()->json([
            'success' => true,
            'sale_id' => $sale->id,
            'invoice_url' => route('pos.invoice', $sale->id),
        ]);
    }

    /**
     * Stream the sale as an 80mm thermal-receipt PDF.
     * Clean layout: no negative margins, everything fits inside the page box.
     */
    public function invoice(Sale $sale)
    {
        $sale->load('items.product', 'customer');

        $balance = $sale->total - $sale->paid_amount;

        $content = '';
        foreach ($sale->items as $item) {
            $content .= '<tr>
                            <td style="text-align:left;">' . e($item->product->name) . '</td>
                            <td style="text-align:center;">' . $item->quantity . '</td>
                            <td>' . number_format($item->price, 1) . '</td>
                            <td>' . number_format($item->total, 1) . '</td>
                        </tr>';
        }

        $htmlContent = '
        <html>
        <head>
            <style>
                * {
                    box-sizing: border-box;
                }
                body {
                    font-family: Arial, sans-serif;
                    margin: 0;
                    padding: 10px 12px;
                    font-size: 12px;
                    color: #000;
                }
                .text-center { text-align: center; }
                .shop-name {
                    font-size: 16px;
                    font-weight: bold;
                    margin: 0;
                }
                .shop-sub {
                    font-size: 11px;
                    margin: 0px 0 10px 0;
                }
                .receipt-title {
                    font-size: 15px;
                    font-weight: bold;
                    margin: 10px 0 2px 0;
                }
                .invoice-no {
                    font-size: 12px;
                    font-weight: bold;
                    margin: 0 0 8px 0;
                }
                .solid-line {
                    border: none;
                    border-bottom: 1px solid #000;
                    margin: 6px 0;
                }
                .dotted-line {
                    border: none;
                    border-bottom: 2px dotted #000;
                    margin: 6px 0;
                }
                table {
                    width: 100%;
                    border-collapse: collapse;
                    font-size: 12px;
                }
                th, td {
                    padding: 3px 2px;
                }
                .meta-table td {
                    padding: 1px 0;
                    font-size: 11px;
                }
                .meta-table .label {
                    font-weight: bold;
                    width: 70px;
                }
                .items-table thead th {
                    border-bottom: 1px solid #000;
                    font-size: 11px;
                }
                .totals-table td {
                    font-size: 12px;
                }
                .totals-table .amt {
                    text-align: right;
                }
                .grand-row td {
                    font-size: 14px;
                    font-weight: bold;
                    padding-top: 6px;
                }
                .thank-you {
                    text-align: center;
                    font-size: 11px;
                    margin-top: 15px;
                }
                @media print {
                    @page {
                        size: 80mm auto;
                        margin: 0;
                    }
                    img {
                        display: block;
                       max-width: 80% !important;
                    }
                    body {
                        width: 80mm;
                    }
                }
            </style>
        </head>
        <body>
            <img style="width:150px; height:120px; display:block; margin-left:60px;" src="data:image/png;base64,"/>

            <p class="text-center" style="margin-top:0px; font-size:12px; margin-left:-20px;">
                <span>Shop 58, Mirwah Road TandoAllahyar.<br></span>
                <span>Phone # 0334-2830393<br></span>
            </p>

            <p class="text-center receipt-title">SALE RECEIPT</p>
            <p class="text-center invoice-no">Invoice # ' . $sale->invoice_no . '</p>

            <hr class="solid-line">

            <table class="meta-table">
                <tr><td class="label">Date:</td><td>' . $sale->created_at->format('d-m-Y h:i A') . '</td></tr>
                <tr><td class="label">Customer:</td><td>' . e($sale->customer->name ?? 'Walk-in Customer') . '</td></tr>
                <tr><td class="label">Phone:</td><td>' . e($sale->customer->phone ?? '-') . '</td></tr>
            </table>

            <hr class="dotted-line">

            <table class="items-table">
                <thead>
                    <tr>
                        <th style="text-align:left;">Item</th>
                        <th style="text-align:center;">Qty</th>
                        <th>Price</th>
                        <th>Total</th>
                    </tr>
                </thead>
                <tbody>
                    ' . $content . '
                </tbody>
            </table>

            <hr class="dotted-line">

            <table class="totals-table">
                <tr>
                    <td>Sub Total:</td>
                    <td class="amt">' . number_format($sale->sub_total, 1) . '</td>
                </tr>
                <tr>
                    <td>Discount:</td>
                    <td class="amt">' . number_format($sale->discount, 1) . '</td>
                </tr>
            </table>

            <hr class="dotted-line">

            <table class="totals-table">
                <tr class="grand-row">
                    <td>Total:</td>
                    <td class="amt">' . number_format($sale->total, 1) . '</td>
                </tr>
                <tr>
                    <td>Paid:</td>
                    <td class="amt">' . number_format($sale->paid_amount, 1) . '</td>
                </tr>
                <tr class="grand-row">
                    <td>' . ($balance > 0 ? 'Balance Due:' : 'Change:') . '</td>
                    <td class="amt">' . number_format(abs($balance), 1) . '</td>
                </tr>
            </table>

            <p class="thank-you">Thank you for your purchase!</p>
        </body>
        </html>';

        $pdf = Pdf::loadHTML($htmlContent)->setPaper([0, 0, 226.77, 841.89], 'portrait');

        return $pdf->stream('invoice-' . $sale->invoice_no . '.pdf');
    }
}